files.game.js:
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const SPEED = 4, JUMP = -11, GRAV = 0.5;

const plats = [
  { x: 0, y: 380, w: 640, h: 20 },
  { x: 90, y: 300, w: 120, h: 14 },
  { x: 270, y: 235, w: 120, h: 14 },
  { x: 440, y: 300, w: 130, h: 14 },
  { x: 270, y: 140, w: 110, h: 14 }
];

let coins = [], player, won = false;

function reset() {
  player = { x: 30, y: 340, vy: 0, onGround: false };
  won = false;
  coins = [
    { x: 150, y: 270 },
    { x: 325, y: 205 },
    { x: 505, y: 270 },
    { x: 320, y: 110 }
  ];
}

const keys = {};
addEventListener('keydown', e => { keys[e.code] = true; if (e.code === 'KeyR') reset(); });
addEventListener('keyup', e => { keys[e.code] = false; });

function step() {
  if (keys.ArrowLeft || keys.KeyA) player.x -= SPEED;
  if (keys.ArrowRight || keys.KeyD) player.x += SPEED;
  const wantJump = keys.ArrowUp || keys.KeyW || keys.Space;
  if (wantJump && player.onGround) { player.vy = JUMP; player.onGround = false; }
  player.vy += GRAV;
  player.y += player.vy;
  player.onGround = false;
  for (const s of plats) {
    const overX = player.x + 24 > s.x && player.x < s.x + s.w;
    if (overX && player.vy >= 0 && player.y + 28 >= s.y && player.y + player.vy + 28 <= s.y + 2) {
      player.y = s.y - 28;
      player.vy = 0;
      player.onGround = true;
    }
  }
  for (const c of coins) {
    if (Math.abs(player.x + 12 - c.x) < 16 && Math.abs(player.y + 14 - c.y) < 16) c.got = true;
  }
  if (player.y > cv.height + 60) reset();
  if (!won && coins.every(c => c.got)) {
    won = true;
    setTimeout(reset, 4000);
  }
}

function draw() {
  ctx.fillStyle = '#1a2332';
  ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = '#4a5568';
  for (const s of plats) ctx.fillRect(s.x, s.y, s.w, s.h);
  ctx.fillStyle = '#ffd23f';
  for (const c of coins) if (!c.got) ctx.fillRect(c.x - 6, c.y - 6, 12, 12);
  ctx.fillStyle = '#3edc81';
  ctx.fillRect(player.x, player.y, 24, 28);
  const left = coins.filter(c => !c.got).length;
  ctx.fillStyle = '#ffffff';
  ctx.font = '16px system-ui';
  ctx.fillText('Coins left: ' + left, 14, 26);
  if (won) ctx.fillText('You win! Reseting in a moment…', 220, 60);
}

reset();
setInterval(() => { step(); draw(); }, 1000 / 60);
